solution:
Let the base triangles have sides $a$ and $b$ with included angle $\theta,$ and let the right prism have altitude $h$.

[asy]
unitsize(1 cm);

pair A, B, C, D, E, F;

A = (0,0);
B = (3,-1);
C = (-1,-2);
D = A + (0,-4);
E = B + (0,-4);
F = C + (0,-4);

draw(A--B--C--cycle);
draw(E--F);
draw(F--D--E,dashed);
draw(A--D,dashed);
draw(B--E);
draw(C--F);

label("$a$", (B + C)/2, S);
label("$b$", (A + C)/2, NW);
label("$h$", (C + F)/2, W);
label("$\theta$", C + (0.4,0.4));
